mapper.select:
SELECT
    COUNT(1)
FROM
    user_post up
    INNER JOIN sys_user u ON u.id = up.user_id
WHERE
    up.post_id = #{postId}
    AND up.status IN (1, 2)

    AND (
        u.username LIKE CONCAT('%', #{query.keyword}, '%')
        OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%')
    )


    AND u.status = #{query.status}


    AND up.status = #{query.relationStatus}


    AND up.is_primary = #{query.isPrimary}

SELECT u.id, u.username, u.status, u.nickname, u.avatar, u.gender, u.employee_no, up.is_primary, up.status AS relation_status FROM user_post up INNER JOIN sys_user u ON u.id = up.user_id WHERE up.post_id = #{postId} AND up.status IN (1, 2)
AND ( u.username LIKE CONCAT('%', #{query.keyword}, '%') OR u.nickname LIKE CONCAT('%', #{query.keyword}, '%') )
AND u.status = #{query.status}
AND up.status = #{query.relationStatus}
AND up.is_primary = #{query.isPrimary}
ORDER BY up.is_primary DESC, up.created_at DESC, u.username
